<template><view class="page"><text class="title">本题反馈</text><text class="line">你猜的是：{{ data.guessedCareer || '未作答' }}</text><text class="line">正确答案：{{ data.correctCareer || '—' }}</text><text class="explain">{{ data.explanation || '' }}</text><text class="label">你对这个职业了解程度</text><view class="choices"><button v-for="x in ['A','B','C']" :key="x" @click="submit(x)">{{x}}</button></view></view></template>
<script>
import { submitAwareness, userMessage } from '@/api/zycck'
export default { data:()=>({recordId:'',instanceId:'',gameId:'',data:{},busy:false}), onLoad(o){this.recordId=o.recordId||'';this.instanceId=o.instanceId||'';this.gameId=o.gameId||'';try{this.data=JSON.parse(decodeURIComponent(o.payload||'{}'))}catch(e){}},methods:{async submit(level){if(this.busy)return;this.busy=true;try{const r=await submitAwareness(this.recordId,{awareness:level});const d=r.data||{};if(d.nextQuestion)uni.redirectTo({url:`/pages/zycck/question?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}`});else uni.redirectTo({url:`/pages/zycck/summary?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}`})}catch(e){uni.showToast({title:userMessage(e,'提交失败，请重试'),icon:'none'})}finally{this.busy=false}}}}
</script>
<style scoped>.page{min-height:100vh;padding:48rpx 40rpx;box-sizing:border-box;background:#f5f7fb;display:flex;flex-direction:column;justify-content:center}.title{display:block;font-size:44rpx;font-weight:700;margin-bottom:32rpx}.line,.explain,.label{display:block;margin:20rpx 0;color:#334155}.explain{line-height:1.7}.choices{display:flex;gap:20rpx}.choices button{flex:1}</style>
